const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = root_module });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Thread-safe in-memory key-value store. Owns copies of all keys and values.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

const KvStore = @This();

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) KvStore {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *KvStore) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.gpa.free(entry.value_ptr.*);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

pub fn put(store: *KvStore, io: Io, key: []const u8, value: []const u8) (Allocator.Error || Io.Cancelable)!PutResult {
    const value_copy = try store.gpa.dupe(u8, value);
    errdefer store.gpa.free(value_copy);

    try store.lock.lock(io);
    defer store.lock.unlock(io);

    const gop = try store.map.getOrPut(store.gpa, key);
    if (gop.found_existing) {
        store.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value_copy;
        return .replaced;
    }
    gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
        store.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = value_copy;
    return .created;
}

/// Returns a copy of the value owned by `arena`, or null if absent.
pub fn get(store: *KvStore, io: Io, arena: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try store.lock.lockShared(io);
    defer store.lock.unlockShared(io);

    const value = store.map.get(key) orelse return null;
    return try arena.dupe(u8, value);
}

pub fn remove(store: *KvStore, io: Io, key: []const u8) Io.Cancelable!bool {
    try store.lock.lock(io);
    defer store.lock.unlock(io);

    const kv = store.map.fetchRemove(key) orelse return false;
    store.gpa.free(kv.key);
    store.gpa.free(kv.value);
    return true;
}

/// Returns copies of every key, sorted ascending, owned by `arena`.
pub fn keys(store: *KvStore, io: Io, arena: Allocator) (Allocator.Error || Io.Cancelable)![][]const u8 {
    const out = blk: {
        try store.lock.lockShared(io);
        defer store.lock.unlockShared(io);

        const out = try arena.alloc([]const u8, store.map.count());
        var it = store.map.keyIterator();
        var i: usize = 0;
        while (it.next()) |key| : (i += 1) {
            out[i] = try arena.dupe(u8, key.*);
        }
        break :blk out;
    };
    std.mem.sortUnstable([]const u8, out, {}, lessThan);
    return out;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

test KvStore {
    const io = testing.io;
    var store: KvStore = .init(testing.allocator);
    defer store.deinit();
    var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqual(.created, try store.put(io, "b", "1"));
    try testing.expectEqual(.replaced, try store.put(io, "b", "2"));
    try testing.expectEqual(.created, try store.put(io, "a", "3"));
    try testing.expectEqualStrings("2", (try store.get(io, arena, "b")).?);
    try testing.expectEqual(null, try store.get(io, arena, "c"));

    const listed = try store.keys(io, arena);
    try testing.expectEqual(2, listed.len);
    try testing.expectEqualStrings("a", listed[0]);
    try testing.expectEqualStrings("b", listed[1]);

    try testing.expect(try store.remove(io, "a"));
    try testing.expect(!try store.remove(io, "a"));
}

//! Minimal HTTP/1.1 server: one request per connection, each connection
//! served by its own concurrent task. Listens on 127.0.0.1.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const net = Io.net;

const http = @import("http.zig");

const Server = @This();

const log = std.log.scoped(.server);

pub const Options = struct {
    port: u16,
    max_head_bytes: usize = 64 * 1024,
    max_body_bytes: usize = 1024 * 1024,
    /// Upper bound on the lifetime of a single connection.
    io_timeout: Io.Duration = .fromSeconds(10),
};

/// Produces a response for a request. All response data must be allocated
/// with `arena`, which lives until the response has been sent.
pub const Handler = struct {
    context: *anyopaque,
    handleFn: *const fn (context: *anyopaque, io: Io, arena: Allocator, request: http.Request) HandlerError!http.Response,

    pub const HandlerError = Allocator.Error || Io.Cancelable;

    fn handle(h: Handler, io: Io, arena: Allocator, request: http.Request) HandlerError!http.Response {
        return h.handleFn(h.context, io, arena, request);
    }
};

gpa: Allocator,
io: Io,
options: Options,
handler: Handler,
listener: net.Server,

pub fn listen(gpa: Allocator, io: Io, options: Options, handler: Handler) net.IpAddress.ListenError!Server {
    const address: net.IpAddress = .{ .ip4 = .loopback(options.port) };
    return .{
        .gpa = gpa,
        .io = io,
        .options = options,
        .handler = handler,
        .listener = try address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 }),
    };
}

pub fn deinit(server: *Server) void {
    server.listener.deinit(server.io);
    server.* = undefined;
}

/// Accept loop; only returns when canceled.
pub fn run(server: *Server) Io.Cancelable!void {
    const io = server.io;
    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = server.listener.accept(io) catch |err| switch (err) {
            error.Canceled => |e| return e,
            error.ConnectionAborted => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                log.err("accept: {t}", .{err});
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => {
                log.err("accept: {t}", .{err});
                continue;
            },
        };
        group.concurrent(io, handleConnection, .{ server, stream }) catch |err| {
            log.err("failed to spawn connection task: {t}", .{err});
            stream.close(io);
        };
    }
}

/// Errors that end a connection. Those with an HTTP status get a response.
const RequestError = error{
    BadRequest,
    ContentTooLarge,
    HeadTooLarge,
    NotImplemented,
    ConnectionClosed,
} || Allocator.Error;

fn errorStatus(err: RequestError) ?u16 {
    return switch (err) {
        error.BadRequest => 400,
        error.ContentTooLarge => 413,
        error.HeadTooLarge => 431,
        error.NotImplemented => 501,
        error.OutOfMemory => 500,
        error.ConnectionClosed => null,
    };
}

fn handleConnection(server: *Server, stream: net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    // Shuts the socket down if the connection outlives its deadline, which
    // unblocks any pending read or write.
    var watchdog: ?Io.Future(Io.Cancelable!void) = io.concurrent(shutdownAfter, .{ io, stream, server.options.io_timeout }) catch |err| blk: {
        log.warn("connection served without timeout: {t}", .{err});
        break :blk null;
    };
    defer if (watchdog) |*w| w.cancel(io) catch {};

    var arena_state: std.heap.ArenaAllocator = .init(server.gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const recv_buffer = arena.alloc(u8, server.options.max_head_bytes) catch return;
    var reader = stream.reader(io, recv_buffer);
    var send_buffer: [4096]u8 = undefined;
    var writer = stream.writer(io, &send_buffer);

    var conn: Connection = .{
        .reader = &reader.interface,
        .writer = &writer.interface,
        .options = &server.options,
    };

    const response, const include_body = if (conn.readRequest(arena)) |request| blk: {
        const response = server.handler.handle(io, arena, request) catch |err| switch (err) {
            error.Canceled => return,
            error.OutOfMemory => http.Response.text(500, "Internal Server Error"),
        };
        break :blk .{ response, !std.mem.eql(u8, request.method, "HEAD") };
    } else |err| blk: {
        const status = errorStatus(err) orelse return;
        break :blk .{ http.Response.text(status, http.reasonPhrase(status)), true };
    };

    conn.send(response, include_body) catch return;
    conn.lingerClose(stream, io);
}

fn shutdownAfter(io: Io, stream: net.Stream, timeout: Io.Duration) Io.Cancelable!void {
    try io.sleep(timeout, .awake);
    stream.shutdown(io, .both) catch {};
}

const Connection = struct {
    reader: *Io.Reader,
    writer: *Io.Writer,
    options: *const Options,

    fn readRequest(conn: *Connection, arena: Allocator) RequestError!http.Request {
        // The head is copied out of the receive buffer, which is reused for the body.
        const head = try arena.dupe(u8, try conn.readHead());
        var request = http.parseHead(arena, head) catch |err| switch (err) {
            error.MalformedRequest => return error.BadRequest,
            error.OutOfMemory => |e| return e,
        };
        request.body = try conn.readBody(arena, request);
        return request;
    }

    /// Returns the request head without its terminating blank line.
    fn readHead(conn: *Connection) RequestError![]const u8 {
        const r = conn.reader;
        var scan_from: usize = 0;
        while (true) {
            const buffered = r.buffered();
            if (std.mem.indexOfPos(u8, buffered, scan_from, "\r\n\r\n")) |end| {
                r.toss(end + 4);
                return buffered[0..end];
            }
            if (buffered.len == r.buffer.len) return error.HeadTooLarge;
            scan_from = buffered.len -| 3;
            r.fillMore() catch return error.ConnectionClosed;
        }
    }

    fn readBody(conn: *Connection, arena: Allocator, request: http.Request) RequestError![]const u8 {
        if (request.header("Transfer-Encoding")) |te| {
            if (!std.ascii.eqlIgnoreCase(te, "chunked")) return error.NotImplemented;
            return conn.readChunkedBody(arena);
        }
        const length_text = request.header("Content-Length") orelse return "";
        const length = http.parseUnsigned(usize, length_text, 10) catch |err| switch (err) {
            error.Overflow => return error.ContentTooLarge,
            error.InvalidCharacter => return error.BadRequest,
        };
        if (length > conn.options.max_body_bytes) return error.ContentTooLarge;

        const body = try arena.alloc(u8, length);
        try conn.readExact(body);
        return body;
    }

    fn readChunkedBody(conn: *Connection, arena: Allocator) RequestError![]const u8 {
        var body: std.ArrayList(u8) = .empty;
        while (true) {
            const line = try conn.readLine();
            const size_text = line[0 .. std.mem.indexOfScalar(u8, line, ';') orelse line.len];
            const size = http.parseUnsigned(usize, size_text, 16) catch return error.BadRequest;
            if (size == 0) {
                // Discard trailer fields up to the terminating blank line.
                while ((try conn.readLine()).len != 0) {}
                return body.items;
            }
            if (size > conn.options.max_body_bytes - body.items.len) return error.ContentTooLarge;
            try conn.readExact(try body.addManyAsSlice(arena, size));
            if ((try conn.readLine()).len != 0) return error.BadRequest;
        }
    }

    fn readExact(conn: *Connection, dest: []u8) RequestError!void {
        conn.reader.readSliceAll(dest) catch |err| return switch (err) {
            error.EndOfStream => error.BadRequest,
            error.ReadFailed => error.ConnectionClosed,
        };
    }

    /// Returns the next CRLF-terminated line, without the terminator. The
    /// slice is only valid until the next read.
    fn readLine(conn: *Connection) RequestError![]const u8 {
        const line = conn.reader.takeDelimiterInclusive('\n') catch |err| return switch (err) {
            error.EndOfStream, error.StreamTooLong => error.BadRequest,
            error.ReadFailed => error.ConnectionClosed,
        };
        if (!std.mem.endsWith(u8, line, "\r\n")) return error.BadRequest;
        return line[0 .. line.len - 2];
    }

    fn send(conn: *Connection, response: http.Response, include_body: bool) error{ConnectionClosed}!void {
        const w = conn.writer;
        response.writeHead(w) catch return error.ConnectionClosed;
        if (include_body) w.writeAll(response.body) catch return error.ConnectionClosed;
        w.flush() catch return error.ConnectionClosed;
    }

    /// Half-closes the socket and discards any remaining input so the client
    /// sees the response rather than a reset.
    fn lingerClose(conn: *Connection, stream: net.Stream, io: Io) void {
        const max_drain = 16 * 1024 * 1024;
        stream.shutdown(io, .send) catch return;
        _ = conn.reader.discard(.limited(max_drain)) catch {};
    }
};

//! Minimal HTTP/1.1 message types and request-head parsing.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Header = struct {
    name: []const u8,
    value: []const u8,
};

pub const Request = struct {
    method: []const u8,
    target: []const u8,
    headers: []const Header,
    body: []const u8 = "",

    /// Case-insensitive header lookup; returns the first match.
    pub fn header(request: Request, name: []const u8) ?[]const u8 {
        for (request.headers) |h| {
            if (std.ascii.eqlIgnoreCase(h.name, name)) return h.value;
        }
        return null;
    }
};

pub const Response = struct {
    status: u16,
    headers: []const Header = &.{},
    body: []const u8 = "",

    pub fn empty(status: u16) Response {
        return .{ .status = status };
    }

    pub fn text(status: u16, body: []const u8) Response {
        return .{
            .status = status,
            .headers = &.{.{ .name = "Content-Type", .value = "text/plain; charset=utf-8" }},
            .body = body,
        };
    }

    /// Writes the status line and headers, including `Content-Length` and
    /// `Connection: close`. The body is not included.
    pub fn writeHead(response: Response, w: *std.Io.Writer) std.Io.Writer.Error!void {
        try w.print("HTTP/1.1 {d} {s}\r\n", .{ response.status, reasonPhrase(response.status) });
        for (response.headers) |h| {
            try w.print("{s}: {s}\r\n", .{ h.name, h.value });
        }
        // 204 responses must not carry a body; Content-Length is omitted there.
        if (response.status != 204) {
            try w.print("Content-Length: {d}\r\n", .{response.body.len});
        }
        try w.writeAll("Connection: close\r\n\r\n");
    }
};

pub fn reasonPhrase(status: u16) []const u8 {
    return switch (status) {
        200 => "OK",
        201 => "Created",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        408 => "Request Timeout",
        411 => "Length Required",
        413 => "Content Too Large",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        505 => "HTTP Version Not Supported",
        else => "Unknown",
    };
}

pub const ParseError = error{MalformedRequest} || Allocator.Error;

/// Parses a request head (request line and header fields, without the
/// terminating blank line). The returned request borrows from `head`; only the
/// header list is allocated with `gpa`.
pub fn parseHead(gpa: Allocator, head: []const u8) ParseError!Request {
    var lines = std.mem.splitSequence(u8, head, "\r\n");

    // Request line: METHOD SP request-target SP HTTP-version
    const request_line = lines.first();
    var parts = std.mem.splitScalar(u8, request_line, ' ');
    const method = parts.first();
    const target = parts.next() orelse return error.MalformedRequest;
    const version = parts.rest();
    if (parts.next() == null) return error.MalformedRequest;
    if (!isToken(method) or target.len == 0 or !std.mem.startsWith(u8, version, "HTTP/1.")) {
        return error.MalformedRequest;
    }

    var headers: std.ArrayList(Header) = .empty;
    errdefer headers.deinit(gpa);
    while (lines.next()) |line| {
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.MalformedRequest;
        const name = line[0..colon];
        if (!isToken(name)) return error.MalformedRequest;
        try headers.append(gpa, .{
            .name = name,
            .value = std.mem.trim(u8, line[colon + 1 ..], " \t"),
        });
    }

    return .{
        .method = method,
        .target = target,
        .headers = try headers.toOwnedSlice(gpa),
    };
}

pub const IntError = error{ InvalidCharacter, Overflow };

/// Strictly parses an unsigned integer: one or more digits in `base`, with no
/// sign, prefix, separators or surrounding whitespace.
pub fn parseUnsigned(comptime T: type, text: []const u8, base: u8) IntError!T {
    if (text.len == 0) return error.InvalidCharacter;
    var result: T = 0;
    for (text) |c| {
        const digit = std.fmt.charToDigit(c, base) catch return error.InvalidCharacter;
        result = std.math.mul(T, result, base) catch return error.Overflow;
        result = std.math.add(T, result, digit) catch return error.Overflow;
    }
    return result;
}

fn isTokenChar(c: u8) bool {
    return std.ascii.isAlphanumeric(c) or std.mem.indexOfScalar(u8, "!#$%&'*+-.^_`|~", c) != null;
}

fn isToken(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s) |c| {
        if (!isTokenChar(c)) return false;
    }
    return true;
}

const testing = std.testing;

test parseHead {
    const request = try parseHead(testing.allocator, "PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-length:  5 ");
    defer testing.allocator.free(request.headers);
    try testing.expectEqualStrings("PUT", request.method);
    try testing.expectEqualStrings("/kv/a", request.target);
    try testing.expectEqualStrings("5", request.header("Content-Length").?);
    try testing.expectEqual(null, request.header("Transfer-Encoding"));
}

test "parseHead rejects malformed heads" {
    const bad = [_][]const u8{
        "GET /health",
        "GET  HTTP/1.1",
        "G(T / HTTP/1.1",
        "GET / HTTP/2",
        "GET / HTTP/1.1\r\nno colon here",
        "GET / HTTP/1.1\r\nbad name: x",
    };
    for (bad) |head| {
        try testing.expectError(error.MalformedRequest, parseHead(testing.allocator, head));
    }
}

test parseUnsigned {
    try testing.expectEqual(@as(usize, 1234), try parseUnsigned(usize, "1234", 10));
    try testing.expectEqual(@as(usize, 0xff), try parseUnsigned(usize, "fF", 16));
    try testing.expectError(error.InvalidCharacter, parseUnsigned(usize, "", 10));
    try testing.expectError(error.InvalidCharacter, parseUnsigned(usize, "+1", 10));
    try testing.expectError(error.InvalidCharacter, parseUnsigned(usize, "1_0", 10));
    try testing.expectError(error.Overflow, parseUnsigned(u16, "65536", 10));
}

test "Response.writeHead" {
    var buf: [256]u8 = undefined;
    var w: std.Io.Writer = .fixed(&buf);
    try Response.text(200, "ok").writeHead(&w);
    try testing.expectEqualStrings(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: 2\r\nConnection: close\r\n\r\n",
        w.buffered(),
    );
}

const std = @import("std");

const http = @import("http.zig");
const KvStore = @import("KvStore.zig");
const routes = @import("routes.zig");
const Server = @import("Server.zig");

pub fn main(init: std.process.Init) !u8 {
    const gpa = init.gpa;
    const io = init.io;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) {
        std.log.err("usage: {s} <port>", .{if (args.len > 0) args[0] else "app"});
        return 2;
    }
    const port = http.parseUnsigned(u16, args[1], 10) catch 0;
    if (port == 0) {
        std.log.err("invalid port: {s}", .{args[1]});
        return 2;
    }

    var store: KvStore = .init(gpa);
    defer store.deinit();

    var server = Server.listen(gpa, io, .{ .port = port }, .{
        .context = &store,
        .handleFn = handle,
    }) catch |err| {
        std.log.err("listen on 127.0.0.1:{d}: {t}", .{ port, err });
        return 1;
    };
    defer server.deinit();

    server.run() catch {};
    return 0;
}

fn handle(context: *anyopaque, io: std.Io, arena: std.mem.Allocator, request: http.Request) Server.Handler.HandlerError!http.Response {
    const store: *KvStore = @ptrCast(@alignCast(context));
    return routes.route(store, io, arena, request);
}

test {
    _ = http;
    _ = KvStore;
    _ = routes;
    _ = Server;
}

//! Dispatches requests against the key-value API.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

const http = @import("http.zig");
const KvStore = @import("KvStore.zig");
const Response = http.Response;
const Request = http.Request;

const kv_prefix = "/kv/";
const max_key_len = 64;

pub const Error = Allocator.Error || Io.Cancelable;

/// Returns true if `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '_' and c != '-') return false;
    }
    return true;
}

/// Produces the response for `request`. Response data is allocated with `arena`.
pub fn route(store: *KvStore, io: Io, arena: Allocator, request: Request) Error!Response {
    const path = request.target;
    if (std.mem.eql(u8, path, "/health")) return handleHealth(request);
    if (std.mem.eql(u8, path, "/kv")) return handleList(store, io, arena, request);
    if (std.mem.startsWith(u8, path, kv_prefix)) {
        return handleKey(store, io, arena, request, path[kv_prefix.len..]);
    }
    return .text(404, "not found");
}

fn methodNotAllowed(comptime allow: []const u8) Response {
    return .{
        .status = 405,
        .headers = &.{
            .{ .name = "Content-Type", .value = "text/plain; charset=utf-8" },
            .{ .name = "Allow", .value = allow },
        },
        .body = "Method Not Allowed",
    };
}

fn isMethod(request: Request, method: []const u8) bool {
    return std.mem.eql(u8, request.method, method);
}

fn handleHealth(request: Request) Response {
    if (!isMethod(request, "GET")) return methodNotAllowed("GET");
    return .text(200, "ok");
}

fn handleList(store: *KvStore, io: Io, arena: Allocator, request: Request) Error!Response {
    if (!isMethod(request, "GET")) return methodNotAllowed("GET");

    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required.
    const keys = try store.keys(io, arena);
    var body: std.Io.Writer.Allocating = .init(arena);
    const w = &body.writer;
    w.writeByte('[') catch return error.OutOfMemory;
    for (keys, 0..) |key, i| {
        if (i != 0) w.writeByte(',') catch return error.OutOfMemory;
        w.print("\"{s}\"", .{key}) catch return error.OutOfMemory;
    }
    w.writeByte(']') catch return error.OutOfMemory;

    return .{
        .status = 200,
        .headers = &.{.{ .name = "Content-Type", .value = "application/json" }},
        .body = body.written(),
    };
}

fn handleKey(store: *KvStore, io: Io, arena: Allocator, request: Request, key: []const u8) Error!Response {
    if (!isValidKey(key)) return .text(400, "invalid key");

    if (isMethod(request, "GET")) {
        const value = try store.get(io, arena, key) orelse return .text(404, "not found");
        return .{
            .status = 200,
            .headers = &.{.{ .name = "Content-Type", .value = "application/octet-stream" }},
            .body = value,
        };
    }
    if (isMethod(request, "PUT")) {
        return switch (try store.put(io, key, request.body)) {
            .created => .empty(201),
            .replaced => .empty(200),
        };
    }
    if (isMethod(request, "DELETE")) {
        return if (try store.remove(io, key)) .empty(204) else .text(404, "not found");
    }
    return methodNotAllowed("GET, PUT, DELETE");
}

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("a/b"));
}

test route {
    const io = testing.io;
    var store: KvStore = .init(testing.allocator);
    defer store.deinit();
    var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const Case = struct { method: []const u8, target: []const u8, body: []const u8 = "", status: u16, response: ?[]const u8 = null };
    const cases = [_]Case{
        .{ .method = "GET", .target = "/health", .status = 200, .response = "ok" },
        .{ .method = "POST", .target = "/health", .status = 405 },
        .{ .method = "GET", .target = "/nope", .status = 404 },
        .{ .method = "GET", .target = "/kv/", .status = 400 },
        .{ .method = "PATCH", .target = "/kv/a.b", .status = 400 },
        .{ .method = "PUT", .target = "/kv/b", .body = "2", .status = 201 },
        .{ .method = "PUT", .target = "/kv/a", .body = "1", .status = 201 },
        .{ .method = "PUT", .target = "/kv/a", .body = "x", .status = 200 },
        .{ .method = "GET", .target = "/kv/a", .status = 200, .response = "x" },
        .{ .method = "PATCH", .target = "/kv/a", .status = 405 },
        .{ .method = "GET", .target = "/kv", .status = 200, .response = "[\"a\",\"b\"]" },
        .{ .method = "DELETE", .target = "/kv", .status = 405 },
        .{ .method = "DELETE", .target = "/kv/a", .status = 204 },
        .{ .method = "DELETE", .target = "/kv/a", .status = 404 },
        .{ .method = "GET", .target = "/kv/a", .status = 404 },
    };
    for (cases) |c| {
        const response = try route(&store, io, arena, .{ .method = c.method, .target = c.target, .headers = &.{}, .body = c.body });
        try testing.expectEqual(c.status, response.status);
        if (c.response) |body| try testing.expectEqualStrings(body, response.body);
    }
}
